function ensureDb(){
  fs.mkdirSync(DATA_DIR,{recursive:true});
  if(!fs.existsSync(DB_FILE)) fs.writeFileSync(DB_FILE, JSON.stringify(seed,null,2));
}
ensureDb();

function readDb(){
  try { return JSON.parse(fs.readFileSync(DB_FILE,"utf8")); }
  catch(e){ fs.writeFileSync(DB_FILE, JSON.stringify(seed,null,2)); return structuredClone(seed); }
}
let db = readDb();

function saveDb(){
  fs.writeFileSync(DB_FILE, JSON.stringify(db,null,2));
}

const sessions = new Map();

function json(res,status,payload){
  const body = JSON.stringify(payload);
  res.writeHead(status, {"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","Access-Control-Allow-Origin":"*"});
  res.end(body);
}
function text(res,status,body,contentType="text/plain; charset=utf-8"){
  res.writeHead(status, {"Content-Type":contentType});
  res.end(body);
}
function parseBody(req){
  return new Promise((resolve,reject)=>{
    let raw="";
    req.on("data",chunk=>{raw+=chunk; if(raw.length>2e6){req.destroy(); reject(new Error("Body too large"));}});
    req.on("end",()=>{ if(!raw) return resolve({}); try{resolve(JSON.parse(raw));}catch(e){reject(e);} });
    req.on("error",reject);
  });
}
function tokenUser(req){
  const auth = req.headers.authorization || "";
  const token = auth.startsWith("Bearer ") ? auth.slice(7) : "";
  return sessions.get(token) || null;
}
function requireAuth(req,res){
  const user = tokenUser(req);
  if(!user){ json(res,401,{error:"Unauthorized"}); return null; }
  return user;
}
function id(prefix){return prefix+"-"+crypto.randomBytes(3).toString("hex").toUpperCase();}
function clone(x){return JSON.parse(JSON.stringify(x));}

function serveFile(req,res){
  let pathname = new URL(req.url, `http://${req.headers.host||"localhost"}`).pathname;
  if(pathname==="/") pathname="/index.html";
  const safe = path.normalize(pathname).replace(/^(\.\.[\/\\])+/, "");
  const file = path.join(ROOT,safe);
  if(!file.startsWith(ROOT)) return text(res,403,"Forbidden");
  fs.readFile(file,(err,data)=>{
    if(err) return text(res,404,"Not found");
    const ext=path.extname(file).toLowerCase();
    const types={".html":"text/html; charset=utf-8",".css":"text/css; charset=utf-8",".js":"text/javascript; charset=utf-8",".json":"application/json",".png":"image/png",".jpg":"image/jpeg",".svg":"image/svg+xml",".ico":"image/x-icon"};
    res.writeHead(200,{"Content-Type":types[ext]||"application/octet-stream","Cache-Control":"no-cache"});
    res.end(data);
  });
}

async function api(req,res){
  const u=new URL(req.url,`http://${req.headers.host||"localhost"}`);
  const p=u.pathname;
  if(req.method==="OPTIONS"){res.writeHead(204,{"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"Content-Type, Authorization","Access-Control-Allow-Methods":"GET,POST,PUT,DELETE,OPTIONS"});return res.end();}
  if(p==="/api/health") return json(res,200,{ok:true,service:"ExamFlow",time:new Date().toISOString()});
  if(p==="/api/login" && req.method==="POST"){
    const body=await parseBody(req);
    if(body.email==="admin@college.edu" && body.password==="demo123456"){
      const token=crypto.randomBytes(24).toString("hex");
      const user={name:"Admin",email:body.email,role:"Admin"};
      sessions.set(token,user);
      return json(res,200,{token,user});
    }
    return json(res,401,{error:"Invalid credentials. Demo: admin@college.edu / demo123456"});
  }
  if(p==="/api/logout" && req.method==="POST"){
    const auth=req.headers.authorization||""; const token=auth.startsWith("Bearer ")?auth.slice(7):"";
    sessions.delete(token); return json(res,200,{ok:true});
  }
  const user=requireAuth(req,res); if(!user) return;

  if(p==="/api/bootstrap" && req.method==="GET"){
    return json(res,200,{user,data:clone(db)});
  }
  if(p==="/api/stats" && req.method==="GET"){
    const open=db.conflicts.filter(x=>x.status==="Open").length;
    return json(res,200,{students:db.students.length, exams:db.exams.length, rooms:db.rooms.filter(r=>r.status==="Available").length, conflicts:open, faculty:db.faculty.length, departments:db.departments.length, sourceFiles:db.meta?.sourceFiles||[]});
  }
  if(p==="/api/generate/timetable" && req.method==="POST"){
    const body=await parseBody(req);
    const departments=Array.isArray(body.departments)&&body.departments.length?body.departments:db.departments.map(x=>x.id);
    const rooms=Array.isArray(body.rooms)&&body.rooms.length?body.rooms:db.rooms.filter(r=>r.status==="Available").map(r=>r.room);
    const slots=Array.isArray(body.slots)&&body.slots.length?body.slots:["09:00 - 12:00","14:00 - 17:00"];
    if(!departments.length) return json(res,400,{error:"Select at least one department"});
    if(!rooms.length) return json(res,400,{error:"Select at least one usable room"});
    if(!slots.length) return json(res,400,{error:"Add at least one time slot"});
    await new Promise(r=>setTimeout(r,250));
    // Replace only the selected departments' schedule. Other departments remain untouched.
    db.exams=db.exams.filter(e=>!departments.includes(e.department));
    let roomIndex=0,slotIndex=0,counter=1;
    const selectedSubjects=(db.subjects||[]).filter(s=>departments.includes(s.department));
    for(const sub of selectedSubjects){
      const dept=sub.department;
      const date=(body.departmentDates&&body.departmentDates[dept])||body.startDate||"2026-09-04";
      const slot=slots[slotIndex++%slots.length];
      let remaining=db.students.filter(s=>s.department===dept).length||30;
      let guard=0;
      while(remaining>0 && guard<rooms.length){
        const roomName=rooms[(roomIndex++)%rooms.length];
        const room=db.rooms.find(r=>r.room===roomName);
        const capacity=room?.capacity||60;
        const assigned=Math.min(capacity,remaining);
        db.exams.push({id:`EX-GEN-${String(counter++).padStart(3,"0")}`,subject:sub.subject,department:dept,date,time:slot,room:roomName,students:assigned,status:"Published"});
        remaining-=assigned; guard++;
      }
      if(remaining>0){
        db.conflicts.unshift({id:id("CF"),type:"Room",severity:"High",title:`Insufficient room capacity for ${sub.subject}`,detail:`${remaining} students remain after using all selected rooms for ${sub.subject} on ${date}.`,status:"Open"});
      }
    }
    db.notifications.unshift({id:id("N"),title:"Timetable generated",text:`${db.exams.length} scheduled exam entries using ${rooms.length} selected rooms and ${slots.length} time slots.`,time:"Just now",type:"success"});
    saveDb();
    return json(res,200,{ok:true,message:"Timetable generated with selected configuration",exams:clone(db.exams),configuration:{departments,rooms,slots,departmentDates:body.departmentDates||{}}});
  }
  if(p==="/api/generate/seats" && req.method==="POST"){
    const body=await parseBody(req);
    const room=body.room || "Hall A";
    const r=db.rooms.find(x=>x.room===room);
    if(!r) return json(res,404,{error:"Room not found"});
    const assigned=Math.min(r.capacity, body.students||r.capacity);
    const columns=Math.max(4,Math.min(12,Number(body.columns)||8));
    db.allocations[room]={rows:Math.ceil(r.capacity/columns),cols:columns,assigned,conflicts:[]};
    db.notifications.unshift({id:id("N"),title:"Seat allocation generated",text:`${assigned} seats assigned in ${room}.`,time:"Just now",type:"success"});
    saveDb();
    return json(res,200,{ok:true,room,assigned,allocation:db.allocations[room]});
  }
  if(p==="/api/conflicts/resolve" && req.method==="POST"){
    const body=await parseBody(req);
    const c=db.conflicts.find(x=>x.id===body.id);
    if(!c) return json(res,404,{error:"Conflict not found"});
    c.status="Resolved";
    c.resolution=body.resolution||"Marked resolved";
    saveDb();
    return json(res,200,{ok:true,conflict:c});
  }

  const match=p.match(/^\/api\/(students|faculty|departments|subjects|rooms|exams|conflicts|notifications)$/);
  if(match){
    const key=match[1];
    if(req.method==="GET") return json(res,200,{items:clone(db[key])});
    if(req.method==="POST"){
      const body=await parseBody(req);
      if(!body || typeof body!=="object") return json(res,400,{error:"Invalid record"});
      const rec=clone(body);
      if(!rec.id && key!=="subjects") rec.id=id(key.slice(0,-1).toUpperCase());
      db[key].push(rec); saveDb(); return json(res,201,{item:rec});
    }
  }
  const itemMatch=p.match(/^\/api\/(students|faculty|departments|subjects|rooms|exams|conflicts|notifications)\/([^/]+)$/);
  if(itemMatch){
    const key=itemMatch[1], ident=decodeURIComponent(itemMatch[2]);
    const arr=db[key]; const idx=arr.findIndex(x=>String(x.id||x.code)===ident);
    if(idx<0) return json(res,404,{error:"Record not found"});
    if(req.method==="GET") return json(res,200,{item:clone(arr[idx])});
    if(req.method==="PUT"){
      const body=await parseBody(req); arr[idx]={...arr[idx],...body}; saveDb(); return json(res,200,{item:clone(arr[idx])});
    }
    if(req.method==="DELETE"){const removed=arr.splice(idx,1)[0];saveDb();return json(res,200,{item:removed});}
  }
  return json(res,404,{error:"API route not found"});
}

const server=http.createServer(async(req,res)=>{
  try{
    if((req.url||"").startsWith("/api/")) await api(req,res);
    else serveFile(req,res);
  }catch(e){
    console.error(e);
    json(res,500,{error:"Internal server error"});
  }
});
server.listen(PORT,HOST,()=>console.log(`ExamFlow running on http://${HOST}:${PORT}`));
